-- Catch-up script: run after 00_setup_source.sql, before "Day 2 - Query".
-- Generated by duckdb/validate.py from Track 3 - Study Case.md; do not edit by hand.

CREATE SCHEMA IF NOT EXISTS bronze;

CREATE SCHEMA IF NOT EXISTS silver;

CREATE SCHEMA IF NOT EXISTS gold;

CREATE SCHEMA IF NOT EXISTS sandbox;

CREATE OR REPLACE TABLE bronze.sales_order_line AS
SELECT *, current_timestamp AS _loaded_at,
       'source.sales_order_line' AS _source
FROM source.sales_order_line;

CREATE OR REPLACE TABLE bronze.sales_order AS
SELECT *, current_timestamp AS _loaded_at,
       'source.sales_order' AS _source
FROM source.sales_order;

CREATE OR REPLACE TABLE bronze.outlet AS
SELECT *, current_timestamp AS _loaded_at,
       'source.outlet' AS _source
FROM source.outlet;

CREATE OR REPLACE TABLE bronze.sku AS
SELECT *, current_timestamp AS _loaded_at,
       'source.sku' AS _source
FROM source.sku;

CREATE OR REPLACE TABLE bronze.distributor AS
SELECT *, current_timestamp AS _loaded_at,
       'source.distributor' AS _source
FROM source.distributor;

CREATE OR REPLACE TABLE bronze.distributor_stock AS
SELECT *, current_timestamp AS _loaded_at,
       'source.distributor_stock' AS _source
FROM source.distributor_stock;

CREATE OR REPLACE TABLE bronze.area AS
SELECT *, current_timestamp AS _loaded_at,
       'source.area' AS _source
FROM source.area;

CREATE OR REPLACE TABLE bronze.region AS
SELECT *, current_timestamp AS _loaded_at,
       'source.region' AS _source
FROM source.region;

-- one row per SKU
CREATE OR REPLACE TABLE silver.dim_sku AS
SELECT ROW_NUMBER() OVER (ORDER BY sk_sku_id) AS sku_key,
       sk_sku_id AS sku_id, sk_name AS sku_name, sk_brand AS brand
FROM bronze.sku;

-- one row per distributor version (ready for SCD Type 2 in Lab 4)
CREATE OR REPLACE TABLE silver.dim_distributor AS
SELECT
    ROW_NUMBER() OVER (ORDER BY d.dt_distributor_id) AS distributor_key,
    d.dt_distributor_id AS distributor_id,
    d.dt_name           AS distributor_name,
    a.ar_name           AS area,
    r.rg_name           AS region,
    DATE '1900-01-01'   AS valid_from,
    CAST(NULL AS DATE)  AS valid_to,
    TRUE                AS is_current
FROM bronze.distributor d
JOIN bronze.area a   ON d.dt_area_id = a.ar_area_id
JOIN bronze.region r ON a.ar_region_id = r.rg_region_id;

-- new distributor versions get keys above the initial load
CREATE OR REPLACE SEQUENCE silver.distributor_key_seq START WITH 1001;

CREATE OR REPLACE TABLE silver.fact_sales_line AS
SELECT
    l.sl_order_id   AS order_id,
    l.sl_line_no    AS line_no,
    o.so_order_date AS order_date,
    ds.sku_key,
    dd.distributor_key,
    l.sl_qty_slof   AS qty_slof,
    l.sl_gross_amount AS gross_amount,
    l.sl_discount   AS discount,
    -- company definition of net sales: after discount, before excise and VAT
    l.sl_gross_amount * (1 - l.sl_discount) AS net_amount
FROM bronze.sales_order_line l
JOIN bronze.sales_order o ON l.sl_order_id = o.so_order_id
JOIN silver.dim_sku ds    ON l.sl_sku_id = ds.sku_id
JOIN silver.dim_distributor dd
    ON  l.sl_distributor_id = dd.distributor_id
    AND o.so_order_date >= dd.valid_from
    AND o.so_order_date <  COALESCE(dd.valid_to, DATE '9999-12-31')
-- keep the latest load of each order line
QUALIFY ROW_NUMBER() OVER (PARTITION BY l.sl_order_id, l.sl_line_no
                           ORDER BY l._loaded_at DESC) = 1
-- load in date order so date filters can skip row groups (Day 2)
ORDER BY order_date;

CREATE OR REPLACE TABLE sandbox.dim_brand AS
SELECT ROW_NUMBER() OVER (ORDER BY brand) AS brand_key, brand
FROM (SELECT DISTINCT brand FROM silver.dim_sku);

CREATE OR REPLACE TABLE sandbox.dim_sku_sf AS
SELECT ds.sku_key, ds.sku_id, ds.sku_name, b.brand_key
FROM silver.dim_sku ds
JOIN sandbox.dim_brand b ON ds.brand = b.brand;

-- close the current version
UPDATE silver.dim_distributor
SET valid_to = current_date, is_current = FALSE
WHERE distributor_id = 42 AND is_current = TRUE;

-- insert the new version with a new surrogate key
INSERT INTO silver.dim_distributor
    (distributor_key, distributor_id, distributor_name, area, region,
     valid_from, valid_to, is_current)
VALUES
    (nextval('silver.distributor_key_seq'), 42, 'Distributor#0042',
     'MAKASSAR', 'INDONESIA TIMUR', current_date, NULL, TRUE);

-- one row per SKU, per distributor, per snapshot date
CREATE OR REPLACE TABLE silver.fact_stock_snapshot AS
SELECT
    current_date AS snapshot_date,
    ds.sku_key,
    dd.distributor_key,
    st.st_stock_slof     AS stock_slof,
    st.st_unit_cost_slof AS unit_cost_slof
FROM bronze.distributor_stock st
JOIN silver.dim_sku ds         ON st.st_sku_id = ds.sku_id
JOIN silver.dim_distributor dd ON st.st_distributor_id = dd.distributor_id
                              AND dd.is_current = TRUE;

-- simulate a second day of snapshots
CREATE OR REPLACE TABLE sandbox.stock_two_days AS
SELECT * FROM silver.fact_stock_snapshot
UNION ALL
SELECT snapshot_date - 1, sku_key, distributor_key, stock_slof, unit_cost_slof
FROM silver.fact_stock_snapshot;

CREATE OR REPLACE VIEW sandbox.flat_sales_report AS
SELECT
    l.sl_order_id, l.sl_line_no, o.so_order_date, o.so_order_source,
    ot.ot_outlet_id, ot.ot_name, ot.ot_channel,
    oa.ar_name AS outlet_area, orr.rg_name AS outlet_region,
    s.sk_sku_id, s.sk_name, s.sk_brand, s.sk_segment,
    d.dt_distributor_id, d.dt_name,
    l.sl_ship_date, l.sl_delivery_date,
    l.sl_qty_slof, l.sl_gross_amount, l.sl_discount
FROM bronze.sales_order_line l
JOIN bronze.sales_order o  ON l.sl_order_id = o.so_order_id
JOIN bronze.outlet ot      ON o.so_outlet_id = ot.ot_outlet_id
JOIN bronze.area oa        ON ot.ot_area_id = oa.ar_area_id
JOIN bronze.region orr     ON oa.ar_region_id = orr.rg_region_id
JOIN bronze.sku s          ON l.sl_sku_id = s.sk_sku_id
JOIN bronze.distributor d  ON l.sl_distributor_id = d.dt_distributor_id;

-- the outlet dimension, straight from bronze
CREATE OR REPLACE TABLE silver.dim_outlet AS
SELECT ROW_NUMBER() OVER (ORDER BY o.ot_outlet_id) AS outlet_key,
       o.ot_outlet_id AS outlet_id, o.ot_name AS outlet_name,
       o.ot_channel AS channel, a.ar_name AS area, r.rg_name AS region
FROM bronze.outlet o
JOIN bronze.area a   ON o.ot_area_id = a.ar_area_id
JOIN bronze.region r ON a.ar_region_id = r.rg_region_id;

-- extend the conformed SKU dimension in place: keys stay stable
ALTER TABLE silver.dim_sku ADD COLUMN segment VARCHAR;

UPDATE silver.dim_sku
SET segment = s.sk_segment
FROM bronze.sku s
WHERE silver.dim_sku.sku_id = s.sk_sku_id;

-- the same fact, now with the outlet key and the order details
CREATE OR REPLACE TABLE silver.fact_sales_line AS
SELECT
    l.sl_order_id      AS order_id,
    l.sl_line_no       AS line_no,
    o.so_order_date    AS order_date,
    o.so_order_source  AS order_source,
    l.sl_ship_date     AS ship_date,
    l.sl_delivery_date AS delivery_date,
    dout.outlet_key,
    ds.sku_key,
    dd.distributor_key,
    l.sl_qty_slof      AS qty_slof,
    l.sl_gross_amount  AS gross_amount,
    l.sl_discount      AS discount,
    l.sl_gross_amount * (1 - l.sl_discount) AS net_amount
FROM bronze.sales_order_line l
JOIN bronze.sales_order o   ON l.sl_order_id = o.so_order_id
JOIN silver.dim_outlet dout ON o.so_outlet_id = dout.outlet_id
JOIN silver.dim_sku ds      ON l.sl_sku_id = ds.sku_id
JOIN silver.dim_distributor dd
    ON  l.sl_distributor_id = dd.distributor_id
    AND o.so_order_date >= dd.valid_from
    AND o.so_order_date <  COALESCE(dd.valid_to, DATE '9999-12-31')
QUALIFY ROW_NUMBER() OVER (PARTITION BY l.sl_order_id, l.sl_line_no
                           ORDER BY l._loaded_at DESC) = 1
ORDER BY order_date;

-- the first gold mart: the dashboard table, built once by the pipeline
CREATE OR REPLACE TABLE gold.mart_sales_outlet_region_month AS
SELECT dout.region,
       DATE_TRUNC('month', f.order_date) AS month_start,
       SUM(f.net_amount)                 AS net_sales,
       COUNT(*)                          AS sales_lines
FROM silver.fact_sales_line f
JOIN silver.dim_outlet dout ON f.outlet_key = dout.outlet_key
GROUP BY dout.region, month_start
ORDER BY month_start;

SELECT 'catch-up done' AS status;